%[text] # Synchrony & Phase Locking 
%[text:tableOfContents]{"heading":"**Table of Contents**"}
%%
%[text] ## von Mises kappa vs PPC and PLV
%[text] Simulates spikes with a range of von Mises kappa synchrony parameters and computes the PPC. Generates a plot to show the relation between the two. The goal is to get an intuitive idea of their relation, which makes chosing a kappa for the simulations easier.
o=artSim;
o.duration =  60*2; % [s] 
o.spikeRate = 100;  
o.spikePeak = 100e-6;
o.refractoryPeriod = 1.5e-3;
o.recordingSamplingRate = 30e3;
o.lfpAmplitude = 5e-6;
o.lfpFrequency = 10;
o.preferredPhase = 0.5*pi;
o.poisson  = true;
%[text] %[text:anchor:TMP_4a4d] Run simulation
kappa =[0:0.1:1 1.5:0.5:5];
nrKappa = numel(kappa);
nrBootstraps = 100;
ppcValue= nan(nrKappa,nrBootstraps);
for k=1:nrKappa
    o.synchrony = kappa(k);
    for bs=1:nrBootstraps
        o.simLfp;
        o.simSpikes;
        [ppcValue(k,bs)] = ppc(o.ixSpike,o.phaseLfp);
    end
end
%[text] %[text:anchor:TMP_0f24] Generate figure
fig('Name','KappaPLV','nrRows',1,'nrCols',1);
yyaxis left
errorbar(kappa,mean(ppcValue,2)',std(ppcValue,0,2)','b');
ylabel 'PPC'
yyaxis right
ppcValue(ppcValue<0)=0;%Upward bias, but good enough
errorbar(kappa,mean(sqrt(ppcValue),2)',std(sqrt(ppcValue),0,2)','r');
ylabel 'PLV'
xlabel 'Von Mises Kappa'


%%
%[text] ## PLV Power Analysis
%[text] How many spikes at a preferred phase does it take to detect a non-zero PLV?
%[text] Simulated spikes that have von Mises tuning for the phase of a tACS signal, and investigated how the power to detect an effect at a given significance level increases with the von Mises kappa. 
%[text] By reading off which PLV value has good power to be detected, we also get an estimate of the % of spikes that artifacts would have to cause to result in incorrect conlcusions about entrainment. 
%[text] Based on the simulations below, for 2 minutes of data with 10 Hz firing rate, this is 5-10%. With longer recordings, this shifts below 5%.
%[text] In other words, if artifacts result in more than 5% of "artifact spikes" in a 180 phase bin then they are likely to affect conclusions about entrainment. Or, conversely, artifact removal has to be better than this to get reliable results.
%%
%[text] %[text:anchor:TMP_6dba] Set Parameters
run('../startup.m')
o=artSim;
o.duration              = 60*2; % [s]  Johnson et al 2 min, Krause et al up to 40 min.
o.spikeRate             = 10;  % [1/s]  Johnson et al , Krause et al 10 Hz
o.spikePeak             = 100e-6; % [muV]
o.recordingSamplingRate = 30e3;
o.lfpAmplitude          = 1;
o.lfpFrequency          = 10;
o.preferredPhase        = 0.5*pi;
o.poisson               = true;

nrPhaseBins = 16;  % Visualization only
kappas      = [0 10.^(-2:0.5:0)]; % Investigate this range of vonMises kappa
nrKappas    = numel(kappas);
nrRepeats   = 10;     % Repeat each set this number of times for a power estimate
nrBootstrap = 10;   % Bootstrap PPC for signficance test.
significanceLevel =0.05; % Alpha level
%%
%[text] Run analysis.
f = figure; %[output:65211765]
set(f,'Name','PLVKappaExample'); %[output:65211765]
R=nrKappas;C= 2;
peakVsTrough = nan(nrRepeats,nrKappas);  % Percentage excess spikes in the 180 degree near preferred.
ppcValue = nan(nrRepeats,nrKappas);      % Computed PPC
pValue =nan(nrRepeats,nrKappas);         % p-Value for PPC>0
t = o.tSimulate;

for i=1:nrKappas %[output:group:5719f647]
    o.synchrony = kappas(i);
    for j= 1:nrRepeats
        o.simLfp;
        o.simSpikes;
        [ppcValue(j,i),pValue(j,i)] = ppc(o.ixSpike,o.phaseLfp,nrBootstrap); %[output:58ee54dc]

        inPreferredHalf = sin(angle(exp(1i*(o.preferredPhase-0.5*pi)).*exp(1i*o.phaseLfp(o.ixSpike))))>0;
        peakVsTrough(j,i) = 100*(sum(inPreferredHalf)-sum(~inPreferredHalf))/numel(inPreferredHalf);

        if j==1
            % Show the first repeat as an example
            subplot(R,C,(i-1)*C+1) %[output:65211765]
            hold on
            % Raster
            oneCycle = 1./o.lfpFrequency;
            nrCycles= o.duration*o.lfpFrequency;
            % Show a "raster"- as all cycles are the same, we can just put the tick at t a
            % random y-level (i.e. a cycle)
            plot(mod(t(o.ixSpike),oneCycle),randi(nrCycles,numel(o.ixSpike),1),'.');
            hold on;
            plot(t(t<oneCycle),0.5*nrCycles*(1+o.lfp(t<oneCycle)))
            title(sprintf('%d Spikes  %3.2f%% Preferred',numel(o.ixSpike),peakVsTrough(j,i)))
            xlim ([0 oneCycle])
            ylim ([0 nrCycles])
            xlabel 'Time in Cycle (s)'
            ylabel 'Cycle'

             subplot(R,C,(i-1)*C+2)       
            % Polar
            polarhistogram(o.phaseLfp(o.ixSpike),nrPhaseBins)
            title(sprintf('PLV: %3.3f',sqrt(max(0,ppcValue(j,i)))))
        end
    end
end %[output:group:5719f647]
%%
%[text] %[text:anchor:TMP_1ed6] Summarize
fig('Name','PLVKappa','nrRows',1,'nrCols',1); %[output:03931e26]
yyaxis left %[output:03931e26]
ax =gca;
h1= plot(kappas,mean(peakVsTrough),'Color',ax.YColor, 'LineStyle','-','Marker','o'); %[output:03931e26]

ylabel 'Excess spikes (%)' %[output:03931e26]
hold on %[output:03931e26]
yyaxis right %[output:03931e26]
ax =gca;
h2= plot(kappas,mean(pValue<significanceLevel),'Color',ax.YColor, 'LineStyle','-','Marker','o'); %[output:03931e26]
hold on %[output:03931e26]
h3 = plot(kappas,sqrt(max(0,mean(ppcValue))),'Color',ax.YColor, 'LineStyle','-','Marker','*'); %[output:03931e26]
ylabel 'Power /PLV ' %[output:03931e26]
legend([h1 h2 h3], 'Excess','Power','PLV','Location','NorthWest') %[output:03931e26]
xlabel 'Kappa' %[output:03931e26]
set(gca,'XScale','Log') %[output:03931e26]
ylim([0 1]) %[output:03931e26]
title ' Power, Kappa, & PLV ' %[output:03931e26]

%%
%[text] ## PLV vs. Spike Rate
%[text] If artifact-induced loss of spikes (i.e. the false negatives seen in `spikes.m`) would be the cause of artifactual entrainment, then one might expect a drop in firing rate. 
%[text] Some claim that a lack of a change in firing rate is evidence against some issue with spike detection or sorting. This however compares a significant result (PLV\>0) with a null result (no change in spike rate). The validity of that claim depends on statistical power. I explore that here by simulating a specific loss fraction (`lossGrid)` across different assumed firing rate. The statistical tests are an exact binomial test for the (assumed Poisson) rate changes, and a Rayleigh or Kuiper test for the PLV. This does not use the PPC to estimate the PLV for simplicity; this should not affect the power of the test (only the estimate of the PLV for low rates).
%% Parameters
rates = [1 5 10 20 60 100];   % vector of baseline rates
recordingTime = 120;          % Seconds
alpha = 0.05;
nrMCSets = 1000;
lossGrid = 0:0.005:0.05;

% Select the deviation-from-uniformity test used for the single-trial power
% calculation. Supported values are 'rayleigh' (default) and 'kuiper' (to allow for axial effects).
uniformityTest = 'kuiper';

% Optional two-sample PLV test.  The baseline PLV is a single scalar shared
% by all firing rates.  Set includeBaselinePLV=false to retain the original
% rate and Rayleigh calculations unchanged.
includeBaselinePLV = true;
baselinePLV = 0.10;
nrPLVPermutations = 1000;
preferredPhase = pi/2;
removedPhaseDifference = pi;

nRates = numel(rates);
nLoss = numel(lossGrid);

mu1 = rates*recordingTime;                               % expected spikes in train 1
p0 = recordingTime/(recordingTime + recordingTime);      % null binomial probability

ratePower = zeros(nRates,nLoss);
uniformityPower = zeros(nRates,nLoss);
plvApprox = zeros(nRates,nLoss);
plvDifferencePower = nan(nRates,nLoss);

%% Vectorized across rates
parfor jf = 1:nLoss

    f = lossGrid(jf);

    % Each column corresponds to one baseline rate
    mu1Matrix = repmat(mu1,nrMCSets,1);
    mu2Matrix = repmat(rates*recordingTime*(1-f),nrMCSets,1);

    n1 = poissrnd(mu1Matrix);
    n2 = poissrnd(mu2Matrix);

    %% Exact Poisson-rate comparison
    nTotal = n1 + n2;
    pLeft = binocdf(n1,nTotal,p0);
    pRight = 1 - binocdf(n1 - 1,nTotal,p0);
    pRate = min(1,2*min(pLeft,pRight));

    % Mean across simulations, retaining one result per rate
    ratePower(:,jf) = mean(pRate < alpha,1).';

    %% Approximate PLV from phase-selective spike deletion
    % Assumes initially uniform phases and removal of fraction f
    % around one phase of the oscillation.
    rho = sin(pi*f)/(pi*(1-f));
    plvApprox(:,jf) = rho;
       %% Deviation-from-uniformity power
    expectedN = rates*recordingTime*(1-f);

       switch lower(uniformityTest)
           case 'rayleigh'
               criticalValue = -2*log(alpha);
               noncentrality = 2*expectedN*rho^2;
               uniformityPower(:,jf) = ...
                   (1 - ncx2cdf(criticalValue,2,noncentrality)).';
           case 'kuiper'
               uniformityPower(:,jf) = estimateKuiperPower(...
                   expectedN,f,nrMCSets,alpha).';
           otherwise
               error('detectPLV:InvalidUniformityTest', ...
                   'uniformityTest must be ''rayleigh'' or ''kuiper''.');
       end

    if includeBaselinePLV
        % Compare an unaltered baseline trial with a trial in which spikes
        % are removed at a phase offset from the baseline preferred phase.
        % A zero offset removes spikes at the preferred phase; pi reproduces
        % the original anti-preferred phase behavior.
        pDifference = false(nrMCSets,nRates);
        for ir = 1:nRates
            for imc = 1:nrMCSets
                nBaseline = n1(imc,ir);
                nTrial = n2(imc,ir);
                baselinePhase = sampleBaselinePhases(nBaseline,baselinePLV,preferredPhase);
                trialPhase = sampleBaselinePhases(nTrial,baselinePLV,preferredPhase);
                nrDropped = round(lossGrid(jf)*nTrial);
                removedPhase = preferredPhase + removedPhaseDifference;
                removedPhaseDistance = abs(angle(exp(1i*(trialPhase - removedPhase))));
                [~,dropOrder] = sort(removedPhaseDistance);
                trialPhase(dropOrder(1:min(nrDropped,nTrial))) = [];

                if numel(trialPhase) < 2 || nBaseline < 2
                    continue
                end

                observed = abs(mean(exp(1i*baselinePhase))) - ...
                    abs(mean(exp(1i*trialPhase)));
                pooled = [baselinePhase; trialPhase];
                nB = nBaseline;
                nullDifference = zeros(nrPLVPermutations,1);
                for ip = 1:nrPLVPermutations
                    shuffled = pooled(randperm(numel(pooled)));
                    nullDifference(ip) = abs(mean(exp(1i*shuffled(1:nB)))) - ...
                        abs(mean(exp(1i*shuffled(nB+1:end))));
                end
                pDifference(imc,ir) = ...
                    mean(abs(nullDifference) >= abs(observed));
            end
        end
        plvDifferencePower(:,jf) = mean(pDifference < alpha,1).';
    end
end
%[text] 
%% Report loss giving >=80% power
fprintf('\nLoss required for 80%% power\n'); %[output:65c25614]
fprintf('Rate       Rate test       %s test\n', ... %[output:group:064a7f9a] %[output:2f534b80]
    [upper(uniformityTest(1)) uniformityTest(2:end)]); %[output:group:064a7f9a] %[output:2f534b80]

for ir = 1:nRates %[output:group:7fdb880c]

    idxRate = find(ratePower(ir,:) >= 0.80,1);
    idxUniformity = find(uniformityPower(ir,:) >= 0.80,1);

    if isempty(idxRate)
        rateLoss = NaN;
    else
        rateLoss = 100*lossGrid(idxRate);
    end

    if isempty(idxUniformity)
        uniformityLoss = NaN;
    else
        uniformityLoss = 100*lossGrid(idxUniformity);
    end

    fprintf('%6.1f/s    %6.2f%%          %6.2f%%n', ... %[output:90d77e7e]
        rates(ir),rateLoss,uniformityLoss); %[output:90d77e7e]
end %[output:group:7fdb880c]

if includeBaselinePLV
    fprintf('\nLoss required for 80%% power: baseline-vs-dropped PLV test\n');
    fprintf('Baseline PLV = %.3f\n',baselinePLV);
    fprintf('Removed-phase offset = %.3f rad\n',removedPhaseDifference);
    fprintf('Rate       PLV difference test\n');
    for ir = 1:nRates
        idxPLVDifference = find(plvDifferencePower(ir,:) >= 0.80,1);
        if isempty(idxPLVDifference)
            plvDifferenceLoss = NaN;
        else
            plvDifferenceLoss = 100*lossGrid(idxPLVDifference);
        end
        fprintf('%6.1f/s    %6.2f%%n',rates(ir),plvDifferenceLoss);
    end
end

%% Plot power curves
figure('Color','w'); %[output:48ae2b59]

for ir = 1:nRates %[output:group:2c5e0914]

    subplot(2,ceil(nRates/2),ir) %[output:48ae2b59]

    plot(100*lossGrid,ratePower(ir,:), ...
        'LineWidth',2, ...
        'DisplayName','Poisson rate test')
    hold on

    plot(100*lossGrid,uniformityPower(ir,:), ...
        '--','LineWidth',2, ...
        'DisplayName',sprintf('%s test', ...
        [upper(uniformityTest(1)) uniformityTest(2:end)]))

    if includeBaselinePLV
        plot(100*lossGrid,plvDifferencePower(ir,:), ...
            ':','LineWidth',2, ...
            'DisplayName','Baseline-vs-dropped PLV test')
    end

    yline(0.80,':k','80% power')

    xlabel('Spikes lost (%)')
    ylabel('Power')
    title(sprintf('\\lambda = %g spikes/s',rates(ir)))
    ylim([0 1])
    grid on

    if ir == 1
        legend('Location','southeast')
    end
end %[output:group:2c5e0914]
%%
%[text] ## Helper Functions
%[text] 
function power = estimateKuiperPower(expectedN,f,nrMCSets,alpha)
% Estimate power of the circular Kuiper test after phase-selective deletion.
power = zeros(size(expectedN));
for ir = 1:numel(expectedN)
    detected = false(nrMCSets,1);
    for imc = 1:nrMCSets
        n = poissrnd(expectedN(ir));
        if n < 2
            continue
        end
        phase = 2*pi*rand(n,1);
        nrDropped = min(round(f*n),n);
        if nrDropped > 0
            distance = abs(angle(exp(1i*phase)));
            [~,dropOrder] = sort(distance);
            phase(dropOrder(1:nrDropped)) = [];
        end
        if numel(phase) >= 2
            detected(imc) = kuiperUniformityPValue(phase) < alpha;
        end
    end
    power(ir) = mean(detected);
end
end

function p = kuiperUniformityPValue(phase)
% Asymptotic p-value for the one-sample circular Kuiper statistic.
u = sort(mod(phase,2*pi)/(2*pi));
n = numel(u);
dPlus = max((1:n)'/n-u);
dMinus = max(u-(0:n-1)'/n);
v = dPlus+dMinus;
lambda = (sqrt(n)+0.155+0.24/sqrt(n))*v;
j = (1:100)';
p = 2*sum((4*j.^2*lambda^2-1).*exp(-2*j.^2*lambda^2));
p = min(1,max(0,p));
end

function phase = sampleBaselinePhases(n, plv, preferredPhase)
%SAMPLEBASELINEPHASES Sample phases with a specified expected baseline PLV.
%   A fraction PLV of spikes is placed at the preferred phase and the
%   remainder is uniform.  Thus the expected complex phase resultant is
%   approximately PLV, while retaining a simple, reproducible null model.

arguments
    n (1,1) double {mustBeNonnegative, mustBeInteger}
    plv (1,1) double {mustBeGreaterThanOrEqual(plv,0), mustBeLessThanOrEqual(plv,1)}
    preferredPhase (1,1) double
end

phase = 2*pi*rand(n,1);
locked = rand(n,1) < plv;
phase(locked) = preferredPhase;
end

